import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


# Kernel source (cuda_sources)
matmul_kernel_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N, int M, int K, int L) {
    long long idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < N * M * L) {
        long long i = idx / (M * L);
        long long rem = idx % (M * L);
        long long j = rem / L;
        long long l = rem % L;
        float sum = 0.0f;
        for (int k = 0; k < K; ++k) {
            int a_idx = i * M * K + j * K + k;
            int b_idx = k * L + l;
            sum += A[a_idx] * B[b_idx];
        }
        C[idx] = sum;
    }
}

torch::Tensor matmul_custom(torch::Tensor A, torch::Tensor B) {
    auto size_A = A.numel();
    const int N = A.size(0);
    const int M = A.size(1);
    const int K = A.size(2);
    const int L = B.size(1); // B shape (K, L)

    auto out = torch::zeros(N, M, L);

    const int block_size = 256;
    const int total_elements = N * M * L;
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    matmul_kernel<<<num_blocks, block_size>>>(A.data_ptr<float()>, B.data_ptr<float()>, out.data_ptr<float()>, N, M, K, L);

    return out;
}
"""

# Function signature source (cpp_sources)
matmul_custom_source = "torch::Tensor matmul_custom(torch::Tensor A, torch::Tensor B);"

# Compile the inline CUDA code
matmul_custom = load_inline(
    name="matmul_custom",
    cpp_sources=matmul_custom_source,
    cuda_sources=matmul_kernel_source,
    functions=["matmul_custom"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

class ModelNew(nn.Module):
    def __init__(self) -> None:
        super().__init__()
        self.matmul_custom = matmul_custom

    def forward(self, A, B):
        return self.matmul_custom(A, B)
